-- surface-guard.lua: the fake game refuses what the real WoW Forever client would refuse.
-- Opt-in: the harness loads it only when WUBER_SURFACE=1 (three small hooks in tests/harness.lua). Data: tests/surface/apisurface.lua
-- (generated by tools/surface/gen-surface.py from the interface source of the client; its header names the build).
-- What it does, for code of a Wuber addon (never for tests or the harness). On by default: U, P, K, S, C. H is OFF until a probe measures it.
--   U  undocumented: calling a global / C_ function / widget method the docs do not list and that is no Blizzard Lua global
--      (blizz list from the interface source) nor a Lua-side helper = would be nil in the game
--   P  protected / SecureOnly / curated "never": any call from addon code is blocked (ReloadUI, RunMacroText, CastSpellByName ...)
--   H  curated "hw": the call needs a hardware click (world.hardware == client), else blocked. ON by default (job 2894); WUBER_SURFACE_HW=off
--      turns it off. Evidence (below) decides whether a hit fails a test or only prints as a lead
--   C  curated "combat": blocked while the player is in combat
--   K  ConstSecretAccessor method (IsEventRegistered, GetAttribute ...) on a frame the game made: answers the secret sentinel and the
--      call is a violation unless its source line guards it with issecretvalue (plain Lua cannot make "== true" fail on a userdata)
--   S  SecretArguments=NotAllowed function called with a secret value
-- EVIDENCE (job 2894): every curated entry (P "never", H, C) carries evidence = "measured:<build>" | "docs" | "brief". Measured: a row in
--   tests/fixtures/probe/measured-blocked.lua (made by tools/rec/probe-import.lua from the passive blocked log of WuberProbe / the Lab's L13.blocked)
--   names the function. Docs: the API docs flag it protected / secure-only. Only measured and docs hits fail a test; a "brief" hit is a LEAD:
--   logged as kind "L" (name TAB where, in WUBER_SURFACE_LOG, and in SG.hits) and never a violation.
-- WRAPPERS (job 2894): a call made through a known thin wrapper (callm, T.Call, pcall ...) is also judged at the next Wuber frame up: the
--   hit names that call site, not the wrapper line.
-- Every hit is a world violation (tests end with clean(w), so the test fails) and a line in WUBER_SURFACE_LOG (kind TAB name TAB where).
-- Env: WUBER_SURFACE_HW=on (try the curated hardware-click rules), WUBER_SURFACE_STRICT=1 (docs + interface definitions only),
--   WUBER_SURFACE_CSA = list (default IsEventRegistered,GetAttribute) | all | none | method names, comma separated,
--   WUBER_SURFACE_LOG = file that gets one line "kind TAB name TAB where" per hit,
--   WUBER_SURFACE_ALLOW = an extra file of "kind:name" lines to skip. The standing allow list is tests/surface/allow.lua (a reason per line).
local SG = {}
local MARK = " (surface guard)"

function SG.new(H, dir)
	local S = dofile(dir .. "/surface/apisurface.lua")
	local self = { S = S, H = H, hits = {}, MARK = MARK }
	local SECRET = H.SECRET
	local State = H.state
	local logPath = os.getenv("WUBER_SURFACE_LOG")
	if logPath == "" then logPath = nil end
	local csaSpec = os.getenv("WUBER_SURFACE_CSA") or "IsEventRegistered,GetAttribute" -- evidence: B4. "all" = every ConstSecretAccessor (strict, noisy: UIParent:GetWidth)
	local csaSet
	if csaSpec ~= "all" and csaSpec ~= "none" then csaSet = {} for n in csaSpec:gmatch("[^,]+") do csaSet[n] = true end end
	local STRICT = os.getenv("WUBER_SURFACE_STRICT") == "1" -- docs + FrameXML definitions only (no "Blizzard code calls it" evidence)
	self.hw = os.getenv("WUBER_SURFACE_HW") ~= "off" -- the curated hardware-click rules: ON by default (job 2894: each entry has its evidence; "brief" ones only print as leads)
	-- measured evidence: tests/fixtures/probe/measured-blocked.lua returns { rows = { { fn =, kind = "BLOCKED"|"FORBIDDEN", combat =, click = true|false|nil, build = }, ... } }
	local measured = {}
	local okM, mrows = pcall(dofile, dir .. "/fixtures/probe/measured-blocked.lua")
	if okM and type(mrows) == "table" then
		for _, r in ipairs(mrows.rows or {}) do
			if type(r.fn) == "string" and type(r.build) == "string" and not measured[r.fn] then measured[r.fn] = "measured:" .. r.build end
		end
	end
	self.measured = measured
	-- how a curated name's evidence is known: measured row, else the table's own docs / brief
	function self.evidence(name, cur)
		return measured[name] or (cur and cur.ev) or "docs"
	end
	-- thin wrappers: the frame running one of these is skipped; the caller one up is judged (keep the list under 10 names)
	local WRAPPERS = { callm = true, Call = true, pcall = true, safecall = true, SafeCall = true, xpcall = true }
	self.WRAPPERS = WRAPPERS
	-- the allow list: tests/surface/allow.lua returns { { "K:Name", "the reason" }, ... }; an entry with no reason is an error
	local allow = {}
	local okAllow, list = pcall(dofile, dir .. "/surface/allow.lua")
	if okAllow and type(list) == "table" then
		for i, e in ipairs(list) do
			if type(e) ~= "table" or type(e[1]) ~= "string" or type(e[2]) ~= "string" or #e[2] < 10 then
				error("tests/surface/allow.lua entry " .. i .. ": needs { \"kind:name\", \"the reason\" }")
			end
			allow[e[1]] = e[2]
		end
	elseif not okAllow and not tostring(list):find("No such file", 1, true) and not tostring(list):find("cannot open", 1, true) then
		error("tests/surface/allow.lua: " .. tostring(list))
	end
	self.allow = allow
	local ap = os.getenv("WUBER_SURFACE_ALLOW")
	if ap and ap ~= "" then for l in io.lines(ap) do local k = l:match("^%s*([^#%s][^%s]*)") if k then allow[k] = "WUBER_SURFACE_ALLOW" end end end

	-- Lua / C-side globals the Blizzard client has that are in neither the docs nor FrameXML Lua (checked by hand; keep short)
	local LUAX = {}
	for n in ([[strsplit strjoin strtrim strlen strsub strupper strlower strfind strmatch strrep strbyte strchar strrev strconcat strlenutf8
		strcmputf8i format gsub gmatch tinsert tremove wipe tContains tIndexOf foreach foreachi getn sort max min floor ceil abs sqrt random
		mod fmod date time difftime hooksecurefunc securecall secureexecuterange issecurevariable issecretvalue canaccessvalue canaccesssecrets
		canaccesstable scrub geterrorhandler seterrorhandler debugstack debugprofilestop debuglocals debugprofilestart GetTime
		loadstring loadfile dofile setfenv getfenv xpcall pcall CreateFrame forceinsecure issecure GetFramesRegisteredForEvent
		securecallfunction tostringall tostringall tonumber tostring ipairs pairs next unpack select type rawget rawset rawequal assert error
		print setmetatable getmetatable collectgarbage gcinfo UnitName CopyTable Mixin CreateFromMixins CreateAndInitFromMixin
		Lerp Clamp Round]]):gmatch("%S+") do LUAX[n] = true end

	local function norm(p) return (p:gsub("^@", ""):gsub("\\", "/")) end
	local function plainDirs(client)
		local t = {}
		for n, d in pairs(H.ADDONS) do t[#t + 1] = { n, norm(d) .. "/" } end
		for n, d in pairs(client.addonDirs or {}) do t[#t + 1] = { n, norm(d) .. "/" } end
		return t
	end
	local function judgedName(n) return n:find("^Wuber") and n ~= "Wuber1" end
	local NOTADDON = { "harness[%w_]*%.lua$", "tests/lib/", "surface%-guard%.lua$", "fakes8%.lua$" }
	-- the file:line of the Wuber addon code that is running: the first frame that is neither C nor the harness. nil: a test (or another addon)
	local function addonCaller(client)
		local dirs, sawTail, viaC, wrapped
		for level = 2, 70 do
			local info = debug.getinfo(level, "Sl")
			if not info then if wrapped then return wrapped[1], wrapped[2], wrapped[3] end return nil end
			if info.what == "tail" then sawTail = true
			elseif info.what == "C" then viaC = true
			else
				local src = norm(info.source or "")
				local skip = false
				for _, pat in ipairs(NOTADDON) do if src:find(pat) then skip = true break end end
				if skip and sawTail then return "(addon code, tail call: line unknown)", "", 0 end
				if not skip then
					dirs = dirs or plainDirs(client)
					local found
					for _, e in ipairs(dirs) do
						local at = src:find(e[2], 1, true)
						if at then
							if not judgedName(e[1]) then return wrapped and wrapped[1], wrapped and wrapped[2], wrapped and wrapped[3] end
							found = { e[1] .. "/" .. src:sub(at + #e[2]) .. ":" .. tostring(info.currentline), src, info.currentline }
							break
						end
					end
					if not found then return wrapped and wrapped[1], wrapped and wrapped[2], wrapped and wrapped[3] end
					if not wrapped and WRAPPERS[debug.getinfo(level, "n").name or ""] then
						wrapped = found -- a thin wrapper: judge the next Wuber frame up (the wrapper's own line is the fallback)
					else
						return found[1], found[2], found[3], viaC
					end
				end
			end
		end
	end

	local function hit(client, kind, name, at, msg, ev)
		if ev == "brief" and kind ~= "G" then kind, msg = "L", nil end -- a "brief" entry is a lead: printed and logged, never a violation
		local key = kind .. ":" .. name
		if allow[key] then return end
		client.surfaceSeen = client.surfaceSeen or {}
		if client.surfaceSeen[key] then return end
		client.surfaceSeen[key] = true
		if kind ~= "G" and #self.hits < 2000 then self.hits[#self.hits + 1] = { kind = kind, name = name, at = at } end -- (capped: memory)
		if logPath then
			local f = io.open(logPath, "a")
			if f then f:write(kind, "\t", name, "\t", at, "\n") f:close() end
		end
		if not msg then return end
		local w = client.world
		w.violations[#w.violations + 1] = client.player.name .. ": " .. msg .. " at " .. at .. MARK
	end
	self.hit = hit

	local function hasSecret(...)
		for i = 1, select("#", ...) do if rawequal((select(i, ...)), SECRET) then return true end end
		return false
	end

	local lineCache = {}
	local function sourceLine(src, n)
		local lines = lineCache[src]
		if not lines then
			lines = {}
			local f = io.open(src, "r")
			if f then for l in f:lines() do lines[#lines + 1] = l end f:close() end
			lineCache[src] = lines
		end
		return lines[n] or ""
	end
	-- a call that sits behind its own feature test ("type(X) == 'function'", "X and X()", "if X then") is the addon being careful: logged "G", not a violation
	local function guarded(src, line, name)
		local short = name:match("([%w_]+)$")
		local pats = {}
		for _, n in ipairs({ name, short }) do
			local e = n:gsub("%p", "%%%0")
			pats[#pats + 1] = "type%([%w_.:]*" .. e .. "%)"
			pats[#pats + 1] = e .. "%s*~=%s*nil"
			pats[#pats + 1] = "%f[%w_]" .. e .. "%s+and%f[%W]"
			pats[#pats + 1] = "if%s+[%w_.]*" .. e .. "%s+then"
			pats[#pats + 1] = "%f[%w_]" .. e .. "%s+or%f[%W]"
			pats[#pats + 1] = "if%s+not%s+[%w_.]*" .. e .. "%f[%W]"
		end
		for l = math.max(1, line - 20), line do
			local text = sourceLine(src, l)
			for _, p in ipairs(pats) do if text:find(p) then return true end end
		end
		return false
	end
	-- the one check of a call. rule: { name, undoc, mode ("never"/"hw"/"combat"), so, p, sa, csa }
	local function check(client, rule, ...)
		if client.rewrite then return end
		local seen = client.surfaceSeen
		local at, src, line, viaC = addonCaller(client)
		if not at then return end
		local name = rule.name
		if rule.mode == "never" or rule.so or rule.p then
			hit(client, "P", name, at, name .. "() is protected / secure-only: blocked from addon code (evidence: " .. tostring(rule.ev or "docs") .. ")", rule.ev)
		elseif rule.mode == "hw" then
			if client.world.hardware ~= client then hit(client, "H", name, at, name .. "() needs a hardware click (not one under way) (evidence: " .. tostring(rule.ev) .. ")", rule.ev) end
		elseif rule.mode == "combat" then
			if client.player.combat then hit(client, "C", name, at, name .. "() is blocked in combat (evidence: " .. tostring(rule.ev) .. ")", rule.ev) end
		elseif rule.undoc then
			-- a call through pcall(fn, ...) or behind its own feature test is the addon being careful too: info only
			if viaC or guarded(src, line, (name:gsub("^[%w_]+:", ""))) then hit(client, "G", name, at, nil)
			else hit(client, "U", name, at, name .. " is not in the API docs for this client (nil in the game)") end
		end
		if rule.sa and hasSecret(...) then hit(client, "S", name, at, name .. "() was given a secret value (SecretArguments=NotAllowed)") end
	end

	local function needsWrap(rule) return rule.undoc or rule.mode or rule.so or rule.p or rule.sa end

	-- a global function of this client's API
	local function ruleGlobal(k)
		local cur = S.curated[k]
		if cur then return { name = k, ev = self.evidence(k, cur), mode = not (not self.hw and cur.mode == "hw") and cur.mode or nil } end
		local d = S.globals[k]
		if d then return { name = k, so = d.so, p = d.p, sa = d.sa } end
		if S.blizz[k] or LUAX[k] or (S.called.g[k] and not STRICT) then return {} end
		return { name = k, undoc = true }
	end
	local function ruleNs(ns, f)
		local full = ns .. "." .. f
		local cur = S.curated[full]
		if cur then return { name = full, ev = self.evidence(full, cur), mode = not (not self.hw and cur.mode == "hw") and cur.mode or nil } end
		local d = S.ns[ns] and S.ns[ns][f]
		if d then return { name = full, so = d.so, p = d.p, sa = d.sa } end
		if S.called.n[full] and not STRICT then return {} end
		return { name = full, undoc = true }
	end

	-- one wrapper per function and rule, kept on the client (it dies with the client's test world). A weak-keyed table in the guard
	-- would keep every fake function of every world alive for the whole process: the wrapper holds its function, and Lua 5.1 has no
	-- ephemerons (a full shard ran out of memory that way)
	local function wrapFn(client, fn, rule)
		local cache = client.surfaceWrap
		if not cache then cache = {} client.surfaceWrap = cache end
		local byName = cache[fn]
		if not byName then byName = {} cache[fn] = byName end
		local w = byName[rule.name]
		if w then return w end
		w = function(...)
			check(client, rule, ...)
			return fn(...)
		end
		byName[rule.name] = w
		return w
	end

	-- per client, after the game's API is complete and before any addon loads
	function self.install(_, client)
		if client.rewrite then return end
		local api = client.api
		local names = {}
		for k, v in pairs(api) do names[#names + 1] = k end
		for k, v in pairs(client.env) do -- globals a test's prepare() put straight on the env
			if type(k) == "string" and type(v) == "function" and rawget(api, k) == nil then
				local rule = ruleGlobal(k)
				if needsWrap(rule) then rawset(client.env, k, wrapFn(client, v, rule)) end
			end
		end
		for _, k in ipairs(names) do
			local v = rawget(api, k)
			if type(k) == "string" and type(v) == "function" then
				local rule = ruleGlobal(k)
				if needsWrap(rule) then api[k] = wrapFn(client, v, rule) end
			elseif type(k) == "string" and k:find("^C_") and type(v) == "table" and not State[v] then
				local mt = getmetatable(v)
				if mt and type(mt.__index) == "function" then
					local old = mt.__index
					mt.__index = function(t, f)
						local x = old(t, f)
						if type(x) == "function" and type(f) == "string" then
							local rule = ruleNs(k, f)
							if needsWrap(rule) then return wrapFn(client, x, rule) end
						end
						return x
					end
				end
			end
		end
	end

	-- the widget classes: once per process. Undocumented methods and ConstSecretAccessor / SecretArguments ones are wrapped in place.
	function self.installClasses()
		if self.classesDone then return end
		self.classesDone = true
		for cname, c in pairs(H.classes or {}) do
			for k, v in pairs(c) do
				if type(k) == "string" and type(v) == "function" and not k:find("^_") then
					local d = S.methods[k]
					local undoc = not d and not LUAX[k] and not (S.called.m[k] and not STRICT)
					local csa = d and d.csa and csaSpec ~= "none" and (not csaSet or csaSet[k])
					local sa = d and d.sa
					if undoc or csa or sa then
						local rule = { name = cname .. ":" .. k, undoc = undoc, sa = sa }
						c[k] = function(obj, ...)
							local s = State[obj]
							local client = s and s.client
							if client and not client.rewrite then
								if undoc or sa then check(client, rule, ...) end
								if csa and client.taintSnap and client.taintSnap.widgets[obj] then
									local at, src, line, viaC = addonCaller(client)
									if at then
										local text = ""
										for l = line, line + 3 do text = text .. " " .. sourceLine(src, l) end -- the call line and the 3 after it
										text = text:lower()
										if viaC or text:find("issecret", 1, true) or text:find("canaccess", 1, true) then
											hit(client, "G", cname .. ":" .. k, at, nil) -- through pcall / a helper: the compare happens elsewhere, not judged
										else
											hit(client, "K", cname .. ":" .. k, at, k .. "() on the game frame " .. tostring(s.name or cname)
												.. " answers a secret value in the game (compare / test it only after issecretvalue)")
										end
										return SECRET
									end
								end
							end
							return v(obj, ...)
						end
					end
				end
			end
		end
	end
	return self
end

return SG
